const Overlay=({children,onClose,title}:{children:React.ReactNode;onClose:()=>void;title:string})=><div className="fixed inset-0 z-[190] overflow-y-auto bg-[#16241f]/45 p-3 backdrop-blur-sm sm:p-6" role="dialog" aria-modal="true"><div className="mx-auto max-w-3xl rounded-[26px] border border-white/60 bg-[#fffefb] shadow-2xl"><header className="flex items-center justify-between border-b border-[#e3e1da] p-5"><h2 className="text-lg font-black">{title}</h2><button onClick={onClose} aria-label="إغلاق" className="grid h-11 w-11 place-items-center rounded-xl hover:bg-[#f1efe8]"><X className="h-5 w-5"/></button></header>{children}</div></div>;
