const emptyPlanForm={name:'',currency:'KWD',priceMinor:0,active:true,activeCompetitions:3,annualParticipants:2500,storageGb:10,branches:3,externalStorage:false,whiteLabel:false,video:false};
const PlanDialog=({open,plan,onClose,onDone}:{open:boolean;plan:any;onClose:()=>void;onDone:()=>void})=>{const [f,setF]=useState(emptyPlanForm),[error,setError]=useState(''),[busy,setBusy]=useState(false);useEffect(()=>{if(!open)return;setError('');setF(plan?{name:plan.name,currency:plan.currency,priceMinor:plan.priceMinor,active:plan.active,activeCompetitions:plan.limits.activeCompetitions,annualParticipants:plan.limits.annualParticipants,storageGb:plan.limits.storageBytes/1024**3,branches:plan.limits.branches,externalStorage:!!plan.features?.external_storage,whiteLabel:!!plan.features?.white_label,video:!!plan.features?.video}:emptyPlanForm)},[open,plan]);if(!open)return null;return <Overlay onClose={onClose} title={plan?'تعديل الخطة':'خطة جديدة'}><form className="grid gap-4 p-6 sm:grid-cols-2" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await api('/api/saas/owner/plans',{method:'PUT',body:JSON.stringify({id:plan?.id,name:f.name,currency:f.currency,priceMinor:f.priceMinor,billingPeriod:'annual',active:f.active,limits:{licensedOrganizations:1,activeCompetitions:f.activeCompetitions,annualParticipants:f.annualParticipants,storageBytes:f.storageGb*1024**3,branches:f.branches},features:{external_storage:f.externalStorage,white_label:f.whiteLabel,video:f.video}})});onDone()}catch(x){setError((x as Error).message)}finally{setBusy(false)}}}><div className="sm:col-span-2"><ErrorNote code={error}/></div><Field lang="ar" data-mizan-kind="arabic" label="اسم الخطة" value={f.name} onChange={e=>setF({...f,name:e.target.value})}/><Field lang="en" data-mizan-kind="latin" dir="ltr" label="العملة" value={f.currency} onChange={e=>setF({...f,currency:e.target.value})}/><Field label="السعر بأصغر وحدة (فلس/سنت)" type="number" value={f.priceMinor} onChange={e=>setF({...f,priceMinor:Number(e.target.value)})}/><Field label="المسابقات النشطة" type="number" value={f.activeCompetitions} onChange={e=>setF({...f,activeCompetitions:Number(e.target.value)})}/><Field label="المتسابقون سنويًا" type="number" value={f.annualParticipants} onChange={e=>setF({...f,annualParticipants:Number(e.target.value)})}/><Field label="التخزين GB" type="number" value={f.storageGb} onChange={e=>setF({...f,storageGb:Number(e.target.value)})}/><Field label="الفروع" type="number" value={f.branches} onChange={e=>setF({...f,branches:Number(e.target.value)})}/><div className="sm:col-span-2 flex flex-wrap gap-4 text-xs font-bold"><label className="mizan-consent"><input type="checkbox" checked={f.active} onChange={e=>setF({...f,active:e.target.checked})}/><span>الخطة نشطة</span></label>{[['التخزين الخاص','externalStorage'],['العلامة البيضاء','whiteLabel'],['الفيديو','video']].map(([label,key])=><label key={key} className="mizan-consent"><input type="checkbox" checked={(f as any)[key]} onChange={e=>setF({...f,[key]:e.target.checked})}/><span>{label}</span></label>)}</div><div className="sm:col-span-2 flex justify-end"><Button disabled={!f.name||busy}>{busy?'جارٍ الحفظ…':'حفظ الخطة'}</Button></div></form></Overlay>};
const OperatorDialog=({open,onClose,onDone}:{open:boolean;onClose:()=>void;onDone:()=>void})=>{const [name,setName]=useState(''),[credits,setCredits]=useState(1),[busy,setBusy]=useState(false),[error,setError]=useState('');if(!open)return null;return <Overlay onClose={onClose} title="إضافة مشغّل معتمد"><form className="space-y-4 p-6" onSubmit={async e=>{e.preventDefault();setBusy(true);try{const r=await api('/api/saas/owner/operators',{method:'POST',body:JSON.stringify({name,pricingTier:'standard',whiteLabelLevel:'mizan'})});const opId=r?.operator?.id;if(opId&&credits>0)await api(`/api/saas/owner/operators/${encodeURIComponent(opId)}/credits`,{method:'POST',body:JSON.stringify({quantity:credits,reason:'رصيد ابتدائي عند إنشاء المشغّل'})});onDone()}catch(x){setError((x as Error).message)}finally{setBusy(false)}}}><ErrorNote code={error}/><Field autoFocus lang="ar" data-mizan-kind="arabic" label="اسم الشركة أو المشغّل" value={name} onChange={e=>setName(e.target.value)}/><label className="block"><span className="mizan-field-label">رصيد الجهات الابتدائي (عدد الجهات المسموح له بإنشائها)</span><input className="mizan-input" type="number" min={0} value={credits} onChange={e=>setCredits(Math.max(0,Math.floor(Number(e.target.value)||0)))}/></label><p className="text-xs leading-6 text-[#666c68]">كل جهة ينشئها المشغّل تستهلك رصيدًا واحدًا. امنحه رصيدًا هنا ليتمكّن من إضافة الجهات مباشرة، أو أبقه صفرًا وامنحه لاحقًا من «إدارة الرصيد».</p><div className="flex justify-end"><Button disabled={busy||!name.trim()}>{busy?'جارٍ الإنشاء…':'إنشاء المشغّل'}</Button></div></form></Overlay>};
const OperatorEditDialog=({operator,onClose,onDone}:{operator:any;onClose:()=>void;onDone:()=>void})=>{const [name,setName]=useState(''),[status,setStatus]=useState('active'),[capGb,setCapGb]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);useEffect(()=>{if(operator){setName(operator.name||'');setStatus(operator.status||'active');setCapGb(operator.storageCapBytes?String(operator.storageCapBytes/1024**3):'');setError('')}},[operator]);if(!operator)return null;const save=async()=>{setBusy(true);try{await api(`/api/saas/owner/operators/${encodeURIComponent(operator.id)}`,{method:'PUT',body:JSON.stringify({name,status,storageCapBytes:capGb.trim()?Math.round(Number(capGb)*1024**3):0})});onDone()}catch(e){setError((e as Error).message)}finally{setBusy(false)}};return <Overlay onClose={onClose} title="تعديل المشغّل"><form className="space-y-4 p-6" onSubmit={e=>{e.preventDefault();void save()}}><ErrorNote code={error}/><div className="rounded-xl bg-[#f3f1eb] p-3 text-[10px] font-bold text-[#626864]" dir="ltr">{operator.id}</div><Field autoFocus lang="ar" data-mizan-kind="arabic" label="اسم الشركة أو المشغّل" value={name} onChange={e=>setName(e.target.value)}/><label><span className="mizan-field-label">الحالة</span><select className="mizan-input" value={status} onChange={e=>setStatus(e.target.value)}><option value="active">نشط</option><option value="suspended">موقوف</option></select></label><label className="block"><span className="mizan-field-label">سقف التخزين لكل جهاته (GB)</span><input className="mizan-input" type="number" min={0} step="1" value={capGb} onChange={e=>setCapGb(e.target.value)} placeholder="اتركه فارغًا = بلا سقف"/><span className="mt-1 block text-[10px] text-[#8d7a52]">يمنع تجاوز مجموع ما تستهلكه جهاته، مهما كانت حصص خططها فرديًا. المستهلك الآن: {gb(operator.storageUsedBytes||0)}</span></label><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>تراجع</Button><Button disabled={!name.trim()||busy}>{busy?'جارٍ الحفظ…':'حفظ التعديل'}</Button></div></form></Overlay>};
const CreditButton=({operator,onDone}:{operator:any;onDone:()=>void})=>{const [open,setOpen]=useState(false),[qty,setQty]=useState(1),[reason,setReason]=useState(''),[error,setError]=useState('');return <div className="mt-4"><Button size="sm" variant="outline" onClick={()=>setOpen(!open)}>إدارة الرصيد</Button>{open&&<div className="mt-3 space-y-2 rounded-xl bg-[#f3f1eb] p-3"><input className="mizan-input" type="number" value={qty} onChange={e=>setQty(Number(e.target.value))}/><input className="mizan-input" value={reason} onChange={e=>setReason(e.target.value)} placeholder="سبب المنح أو التعديل"/><ErrorNote code={error}/><Button size="sm" disabled={!qty||reason.trim().length<3} onClick={async()=>{try{await api(`/api/saas/owner/operators/${operator.id}/credits`,{method:'POST',body:JSON.stringify({quantity:qty,reason})});setOpen(false);onDone()}catch(e){setError((e as Error).message)}}}>تسجيل التعديل</Button></div>}</div>};
const RequestRow=({request:r,onDone}:{request:any;onDone:()=>void})=>{const [note,setNote]=useState(''),[busy,setBusy]=useState(false),[err,setErr]=useState('');const decide=async(decision:string)=>{setBusy(true);setErr('');try{await api(`/api/saas/owner/change-requests/${r.id}/decision`,{method:'POST',body:JSON.stringify({decision,note})});onDone()}catch(e){setErr((e as Error).message)}finally{setBusy(false)}};return <div className="mizan-panel p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><div className="flex items-center gap-2"><h3 className="font-black">{r.organizationId}</h3><Badge variant={r.status==='pending'?'amber':r.status==='approved'?'emerald':'neutral'}>{r.status}</Badge></div><div className="mt-3 grid gap-2 text-xs sm:grid-cols-2"><div className="rounded-xl bg-[#f3f1eb] p-3"><div className="text-[10px] text-[#6c726e]">القيمة الحالية · {r.field}</div><div className="mt-1 font-bold">{r.currentValue||'—'}</div></div><div className="rounded-xl bg-[#eaf1ed] p-3"><div className="text-[10px] text-[#557066]">القيمة المطلوبة</div><div className="mt-1 font-black">{r.requestedValue}</div></div></div><p className="mt-3 text-xs text-[#666c68]">{r.reason}</p></div>{r.status==='pending'&&<div className="w-full lg:max-w-xs"><input className="mizan-input" value={note} onChange={e=>setNote(e.target.value)} placeholder="ملاحظة القرار"/>{err&&<div className="mt-2"><ErrorNote code={err}/></div>}<div className="mt-2 flex gap-2"><Button size="sm" disabled={busy} onClick={()=>void decide('approved')}>قبول</Button><Button size="sm" variant="outline" disabled={busy||note.length<3} onClick={()=>void decide('needs_information')}>معلومات إضافية</Button><Button size="sm" variant="ghost" disabled={busy||note.length<3} onClick={()=>void decide('rejected')}>رفض</Button></div></div>}</div></div>};

export const OrganizationLicenseCenter:React.FC=()=>{const {language,organization}=useAppStore(),ar=language==='ar';const [data,setData]=useState<any>(null),[error,setError]=useState(''),[tab,setTab]=useState<'usage'|'identity'|'storage'>('usage'),[requestOpen,setRequestOpen]=useState(false);const load=useCallback(async()=>{try{setData(await api('/api/saas/organization'));setError('')}catch(e){setError((e as Error).message)}},[]);useEffect(()=>{void load()},[load]);if(!data)return <div className="space-y-3"><ErrorNote code={error}/><div className="mizan-panel p-6 text-xs text-[#666c68]">{ar?'بيانات الترخيص غير متاحة بعد. قد تحتاج الجهة الحالية إلى ترحيل آمن من سجل الجهات القديم.':'License data is not available yet.'}</div></div>;const {organization:o,license,usage}=data;return <div className="space-y-4"><Tabs value={tab} onChange={setTab} items={[{id:'usage',label:'الاستخدام والخطة'},{id:'identity',label:'هوية الترخيص'},{id:'storage',label:'التخزين'}]}/><ErrorNote code={error}/>{tab==='usage'&&<div className="grid gap-4 lg:grid-cols-[1.2fr_.8fr]"><div className="mizan-surface p-5 sm:p-6"><div className="mizan-kicker">الاستخدام</div><div className="mt-5 space-y-6"><Meter label="المسابقات النشطة" used={usage.activeCompetitions} total={license.limits.activeCompetitions}/><Meter label="المتسابقون هذا العام" used={usage.annualParticipants} total={license.limits.annualParticipants}/><Meter label="تخزين ميزان" used={usage.mizanStorageBytes} total={license.limits.storageBytes} detail={`${gb(usage.mizanStorageBytes)} / ${gb(license.limits.storageBytes)}`}/></div></div><div className="mizan-surface p-5"><div className="mizan-kicker">الترخيص</div><h3 className="mt-2 text-xl font-black">{license.planId}</h3><div className="mt-5 space-y-2"><QuietRow label="الحالة" value={arStatus(license.status)}/><QuietRow label="البداية" value={date(license.startsAt)}/><QuietRow label="صالح حتى" value={date(license.expiresAt)}/><QuietRow label="العلامة البيضاء" value={license.whiteLabelEnabled?'مفعّلة':'غير مشمولة'}/></div></div></div>}{tab==='identity'&&<div className="mizan-surface p-5 sm:p-6"><div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><div className="mizan-kicker">الجهة المرخصة</div><h3 className="mt-2 text-xl font-black">{o.officialName}</h3><div className="mt-2 text-xs text-[#666c68]" dir="ltr">{o.licenseId}</div></div><Button variant="outline" size="sm" onClick={()=>setRequestOpen(true)}>طلب تعديل بيانات الجهة</Button></div><div className="mt-6 grid gap-3 sm:grid-cols-2"><Locked label="الاسم القانوني الرسمي" value={o.officialName}/><Locked label="معرّف الجهة" value={o.id} ltr/><Locked label="معرّف المستأجر" value={o.tenantId} ltr/><Locked label="معرّف الترخيص" value={o.licenseId} ltr/><Locked label="الدولة القانونية" value={o.country}/><Locked label="الجهة المالكة للترخيص" value={o.operatorId||'ميزان مباشرة'}/></div><div className="mt-5 rounded-xl bg-[#f3f1eb] p-4 text-xs leading-6 text-[#666c68]"><ShieldCheck className="mb-2 h-4 w-4 text-[#2F6555]"/>هذه البيانات جزء من هوية الترخيص ولا تُحرر كحقول عادية. التغيير يمر بطلب موثق وموافقة مالك المنصة.</div></div>}{tab==='storage'&&<StoragePanel data={data} reload={load}/>}<ChangeRequestDialog open={requestOpen} onClose={()=>setRequestOpen(false)} organization={o} onDone={()=>{setRequestOpen(false);void load()}}/></div>};
const Locked=({label,value,ltr}:{label:string;value:string;ltr?:boolean})=><div className="rounded-2xl border border-[#e2e0d9] bg-white p-4"><div className="flex items-center gap-2 text-[10px] font-black text-[#6c726e]"><KeyRound className="h-3.5 w-3.5"/>{label}</div><div className="mt-2 text-sm font-black" dir={ltr?'ltr':undefined}>{value||'—'}</div></div>;
const ChangeRequestDialog=({open,onClose,organization,onDone}:{open:boolean;onClose:()=>void;organization:any;onDone:()=>void})=>{const [field,setField]=useState('officialName'),[value,setValue]=useState(''),[reason,setReason]=useState(''),[error,setError]=useState('');if(!open)return null;return <Overlay onClose={onClose} title="طلب تعديل هوية الجهة"><form className="space-y-4 p-6" onSubmit={async e=>{e.preventDefault();try{await api('/api/saas/organization/change-requests',{method:'POST',body:JSON.stringify({field,requestedValue:value,reason})});onDone()}catch(x){setError((x as Error).message)}}}><ErrorNote code={error}/><label><span className="mizan-field-label">الحقل</span><select className="mizan-input" value={field} onChange={e=>setField(e.target.value)}><option value="officialName">الاسم القانوني الرسمي</option><option value="country">الدولة القانونية</option><option value="legalEmail">البريد القانوني</option><option value="legalPhone">الهاتف القانوني</option></select></label><Locked label="القيمة الحالية" value={String(organization[field]||'—')}/><Field label="القيمة المطلوبة" value={value} onChange={e=>setValue(e.target.value)}/><label><span className="mizan-field-label">سبب التعديل</span><textarea className="mizan-input min-h-24 resize-y" value={reason} onChange={e=>setReason(e.target.value)}/><span className="mt-1 block text-[10px] text-[#8d7a52]">{!value.trim()?'أدخل القيمة المطلوبة.':reason.trim().length<5?'اكتب سبباً من ٥ أحرف فأكثر لتفعيل الإرسال.':'جاهز للإرسال.'}</span></label><div className="flex justify-end"><Button disabled={!value.trim()||reason.trim().length<5}>إرسال الطلب</Button></div></form></Overlay>};
const StoragePanel=({data,reload}:{data:any;reload:()=>void})=>{const [connect,setConnect]=useState(false);const u=data.usage,l=data.license;return <div className="grid gap-4 lg:grid-cols-2"><div className="mizan-surface p-5"><div className="flex items-start justify-between"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#e8f0eb] text-[#28594a]"><Database className="h-5 w-5"/></div><Badge variant="emerald">نشط</Badge></div><h3 className="mt-4 text-lg font-black">تخزين ميزان</h3><p className="mt-2 text-xs leading-6 text-[#666c68]">مُدار بالكامل من ميزان، والملفات المشتركة للنظام لا تُحتسب على الجهة.</p><div className="mt-5"><Meter label="المستخدم" used={u.mizanStorageBytes} total={l.limits.storageBytes} detail={`${gb(u.mizanStorageBytes)} / ${gb(l.limits.storageBytes)}`}/></div></div><div className="mizan-surface p-5"><div className="flex items-start justify-between"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#edf0f2] text-[#496477]"><Globe2 className="h-5 w-5"/></div><Badge variant={data.storageAccounts?.[0]?.connectionStatus==='connected'?'emerald':'neutral'}>{data.storageAccounts?.[0]?.connectionStatus||'غير مربوط'}</Badge></div><h3 className="mt-4 text-lg font-black">التخزين الخاص بالجهة</h3><p className="mt-2 text-xs leading-6 text-[#666c68]">اربط مساحة مؤسستك بأمان. لا يظهر مفتاحك بعد الحفظ ولا يُعاد من الخادم.</p>{data.storageAccounts?.length?<div className="mt-4 rounded-xl bg-[#f3f1eb] p-3 text-xs"><QuietRow label="المزوّد" value={data.storageAccounts[0].provider}/><QuietRow label="آخر اختبار" value={data.storageAccounts[0].lastTestedAt?date(data.storageAccounts[0].lastTestedAt):'لم يُختبر'}/></div>:<Button className="mt-5" variant="outline" onClick={()=>setConnect(true)}>ربط التخزين الخاص</Button>}</div><StorageWizard open={connect} onClose={()=>setConnect(false)} onDone={()=>{setConnect(false);reload()}}/></div>};
const StorageWizard=({open,onClose,onDone}:{open:boolean;onClose:()=>void;onDone:()=>void})=>{const [step,setStep]=useState(1),[f,setF]=useState({provider:'cloudflare_r2',container:'',region:'',endpoint:'',accessKey:'',secretKey:''}),[error,setError]=useState('');if(!open)return null;const save=async()=>{try{await api('/api/saas/organization/storage',{method:'POST',body:JSON.stringify({provider:f.provider,container:f.container,region:f.region,endpoint:f.endpoint,secret:{accessKey:f.accessKey,secretKey:f.secretKey}})});onDone()}catch(e){setError((e as Error).message)}};return <Overlay onClose={onClose} title="ربط التخزين الخاص"><div className="p-6"><div className="mb-6 text-xs font-bold text-[#666c68]">الخطوة {step} من 5 · {['اختيار المزوّد','بيانات الحساب','المساحة','اختبار الاتصال','التأكيد'][step-1]}</div><ErrorNote code={error}/>{step===1&&<div className="grid gap-3 sm:grid-cols-2">{[['cloudflare_r2','Cloudflare R2'],['amazon_s3','Amazon S3'],['google_cloud_storage','Google Cloud Storage'],['azure_blob','Azure Blob Storage']].map(([v,n])=><button key={v} onClick={()=>{setF({...f,provider:v});setStep(2)}} className={`rounded-2xl border p-5 text-start font-black ${f.provider===v?'border-[#2F6555] bg-[#edf3ef]':'border-[#e0ded7]'}`}>{n}</button>)}</div>}{step===2&&<div className="grid gap-4"><Field label="Access key / Client ID" value={f.accessKey} onChange={e=>setF({...f,accessKey:e.target.value})}/><Field label="Secret" type="password" autoComplete="new-password" value={f.secretKey} onChange={e=>setF({...f,secretKey:e.target.value})}/><p className="text-[10px] leading-5 text-[#666c68]">يُرسل السر مرة واحدة عبر اتصال HTTPS، ويُحفظ مشفرًا في خزنة منفصلة. لن يظهر هنا مجددًا.</p></div>}{step===3&&<div className="grid gap-4"><Field label="Bucket / Container" value={f.container} onChange={e=>setF({...f,container:e.target.value})}/><Field label="Region (اختياري)" value={f.region} onChange={e=>setF({...f,region:e.target.value})}/><Field label="Endpoint (عند الحاجة)" value={f.endpoint} onChange={e=>setF({...f,endpoint:e.target.value})}/></div>}{step===4&&<div className="rounded-2xl bg-[#f3f1eb] p-5"><h3 className="font-black">اختبار ثلاثي قبل الاعتماد</h3><p className="mt-2 text-xs leading-6 text-[#666c68]">سينفذ ميزان رفع ملف اختبار، ثم قراءته، ثم حذفه. لن يصبح التخزين نشطًا ما لم تنجح الخطوات الثلاث.</p></div>}{step===5&&<div className="rounded-2xl bg-[#edf3ef] p-5 text-xs"><QuietRow label="المزوّد" value={f.provider}/><QuietRow label="المساحة" value={f.container}/><QuietRow label="المنطقة" value={f.region||'اكتشاف تلقائي'}/></div>}<div className="mt-6 flex justify-between"><Button variant="ghost" disabled={step===1} onClick={()=>setStep(s=>s-1)}>السابق</Button>{step<5?<Button disabled={(step===2&&(!f.accessKey||!f.secretKey))||(step===3&&!f.container)} onClick={()=>setStep(s=>s+1)}>التالي</Button>:<Button onClick={()=>void save()}>حفظ ثم اختبار</Button>}</div></div></Overlay>};

export const OperatorWorkspace:React.FC=()=>{const [data,setData]=useState<any>(null),[error,setError]=useState(''),[createOpen,setCreateOpen]=useState(false),[accessOrgId,setAccessOrgId]=useState(''),[domainOrgId,setDomainOrgId]=useState(''),[opTab,setOpTab]=useState<'orgs'|'plans'|'billing'>('orgs');const load=useCallback(async()=>{try{setData(await api('/api/saas/operator/dashboard'));setError('')}catch(e){setError((e as Error).message)}},[]);useEffect(()=>{void load();const id=window.setInterval(()=>void load(),20000);return()=>window.clearInterval(id)},[load]);useEffect(()=>{if(!data)return;const openIdentityTarget=()=>{const params=identityDeepLink();if(!params)return;const organizationId=params.get('organizationId')||'',operatorId=params.get('operatorId')||'';if(organizationId&&(data.organizations||[]).some((x:any)=>x.organization?.id===organizationId)){setAccessOrgId(organizationId);return}if(!organizationId&&(!operatorId||operatorId===data.operator?.id))setAccessOrgId('')};openIdentityTarget();window.addEventListener('hashchange',openIdentityTarget);return()=>window.removeEventListener('hashchange',openIdentityTarget)},[data]);if(!data)return <div className="mizan-page"><ErrorNote code={error}/></div>;const active=data.organizations.reduce((n:number,x:any)=>n+x.usage.activeCompetitions,0),participants=data.organizations.reduce((n:number,x:any)=>n+x.usage.annualParticipants,0);return <div className="space-y-5"><div className="mizan-hero"><div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><div className="mizan-kicker">مشغّل معتمد</div><h1 className="mt-2 text-3xl font-black">أعمالي على ميزان</h1><p className="mt-2 text-xs text-[#666c68]">{data.operator.name} · كل عميل جهة مستقلة بترخيص وبيانات وتخزين معزول.</p></div><Button size="sm" icon={<Plus className="h-4 w-4"/>} disabled={data.creditBalance<1} title={data.creditBalance<1?'يلزم رصيد جهة واحد على الأقل لإنشاء جهة':undefined} onClick={()=>setCreateOpen(true)}>جهة جديدة</Button></div></div><ErrorNote code={error}/>{data.creditBalance<1&&<div className="rounded-2xl border border-[#d8c7a7] bg-[#fffaf0] px-4 py-3 flex items-start gap-3"><WalletCards className="h-4 w-4 text-[#8b6837] shrink-0 mt-0.5"/><div><div className="text-xs font-black text-[#604724]">لا يوجد رصيد جهات في حسابك بعد</div><p className="mt-1 text-[10px] leading-5 text-[#6b5b45]">كل جهة جديدة تستهلك رصيد ترخيص واحدًا. يمنحك مالك المنصة الرصيد من «المشغّلون ← إدارة الرصيد»، وبعدها يصبح زر «جهة جديدة» فعّالًا مباشرة.</p></div></div>}<div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric icon={Building2} value={data.organizations.length} label="جهة"/><Metric icon={Layers3} value={active} label="مسابقة نشطة"/><Metric icon={UsersRound} value={participants} label="متسابق هذا العام"/><Metric icon={WalletCards} value={data.creditBalance} label="رصيد الجهات" tone="amber"/></div><Tabs value={opTab} onChange={setOpTab} items={[{id:'orgs',label:'الجهات',count:data.organizations.length},{id:'plans',label:'باقاتي',count:(data.ownedPlans||[]).length},{id:'billing',label:'الفوترة',count:data?.billing?.summary?.openInvoices||undefined}]}/>{opTab==='orgs'&&<><div className="mizan-surface overflow-hidden"><div className="border-b border-[#e3e1da] p-5"><h2 className="font-black">الجهات التابعة</h2><p className="mt-1 text-xs text-[#666c68]">لا تظهر هنا إلا الجهات المرتبطة بهذا المشغّل. افتح بطاقة الجهة لدعوة مديرها الأول.</p></div><div className="divide-y divide-[#e5e3dc]">{data.organizations.map((x:any)=>{const open=accessOrgId===x.organization.id;return <div key={x.organization.id} className="p-4"><div className="grid gap-3 sm:grid-cols-[1fr_auto_auto_auto_auto] sm:items-center"><div><div className="font-black">{x.organization.officialName}</div><div className="mt-1 text-[10px] text-[#6c726e]" dir="ltr">{x.organization.id}</div></div><span className="text-xs">{x.license?.planId}</span><span className="text-xs" dir="ltr">{gb(x.usage.mizanStorageBytes)}</span><Badge variant={x.organization.status==='active'?'emerald':'neutral'}>{arStatus(x.organization.status)}</Badge><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" icon={<ShieldCheck className="h-4 w-4"/>} onClick={()=>{setDomainOrgId('');setAccessOrgId(open?'':x.organization.id)}}>{open?'إغلاق الوصول':'مدير الجهة'}</Button><Button size="sm" variant="outline" icon={<Globe2 className="h-4 w-4"/>} onClick={()=>{setAccessOrgId('');setDomainOrgId(domainOrgId===x.organization.id?'':x.organization.id)}}>{domainOrgId===x.organization.id?'إغلاق النطاق':'النطاق والوصول'}</Button></div></div>{open&&<div className="mt-4 border-t border-[#e5e3dc] pt-4"><IdentityGovernance organizationId={x.organization.id}/></div>}{domainOrgId===x.organization.id&&<div className="mt-4 border-t border-[#e5e3dc] pt-4"><TenantDomainCard orgId={x.organization.id} getUrl={`/api/saas/operator/organizations/${encodeURIComponent(x.organization.id)}/domain`} patchUrl={`/api/saas/operator/organizations/${encodeURIComponent(x.organization.id)}/domain`} lockWhenSet confirmOnSave/></div>}</div>})}{!data.organizations.length&&<EmptyState icon={Building2} title="لا توجد جهات حتى الآن" hint="استخدم رصيد الجهة لإنشاء مساحة مستقلة لأول عميل."/>}</div></div><IdentityGovernance operatorId={data.operator.id} operatorName={data.operator.name}/></>}{opTab==='plans'&&<OperatorPlansPanel plans={data.ownedPlans||[]} onDone={load}/>}{opTab==='billing'&&<BillingPanel mine gateway={data.paymentGateway} billing={data.billing} base="/api/saas/operator" plans={(data.plans||[]).filter((p:any)=>p.ownerOperatorId===data.operator.id)} onDone={load} subjects={(data.organizations||[]).map((x:any)=>({type:'organization' as const,id:x.organization.id,name:x.organization.officialName}))}/>}<OrganizationWizard key={createOpen?'operator-organization-create-open':'operator-organization-create-closed'} open={createOpen} onClose={()=>setCreateOpen(false)} data={data} endpoint="/api/saas/operator/organizations" hideOwnership onDone={()=>{setCreateOpen(false);void load()}}/></div>};

/* ————— الفوترة والاشتراكات: لوحة واحدة يستخدمها مالك المنصة والمشغّل بنفس الوضوح ————— */
const money=(minor:number,currency='KWD')=>`${((Number(minor)||0)/100).toLocaleString('ar-KW-u-nu-latn',{minimumFractionDigits:2,maximumFractionDigits:2})} ${currency}`;
const SUB_AR:Record<string,string>={active:'نشط',trialing:'تجريبي',past_due:'متأخر',canceled:'ملغى',unpaid:'غير مدفوع'};
const INV_AR:Record<string,string>={draft:'مسودة',open:'بانتظار السداد',paid:'مدفوعة',void:'ملغاة',uncollectible:'متعذّر تحصيلها'};
const invTone=(s:string)=>s==='paid'?'emerald':s==='open'?'amber':'neutral';
const subTone=(s:string)=>s==='active'?'emerald':s==='past_due'||s==='unpaid'?'amber':'neutral';
const sumMinor=(rows:{amountMinor:number}[])=>rows.reduce((n,x)=>n+(Number(x.amountMinor)||0),0);

const BillingPanel=({billing,subjects,plans,base,onDone,mine,gateway}:{billing:any;subjects:{type:'operator'|'organization';id:string;name:string}[];plans:any[];base:string;onDone:()=>void;mine?:boolean;gateway?:{configured?:boolean;name?:string}})=>{
 const [error,setError]=useState(''),[busy,setBusy]=useState(''),[subOpen,setSubOpen]=useState(false),[invOpen,setInvOpen]=useState(false),[filter,setFilter]=useState<'all'|'open'|'overdue'|'paid'>('all');
 const summary=billing?.summary||{},subs=billing?.subscriptions||[],invoices=billing?.invoices||[];
 const shown=invoices.filter((i:any)=>filter==='all'?true:filter==='overdue'?i.overdue:i.status===filter);
 const act=async(path:string,body?:any)=>{setBusy(path);setError('');try{await api(path,{method:'POST',body:body?JSON.stringify(body):undefined});onDone()}catch(e){setError((e as Error).message)}finally{setBusy('')}};
 const payOnline=async(invoiceId:string)=>{const path=`${base}/invoices/${encodeURIComponent(invoiceId)}/checkout`;setBusy(path);setError('');try{const out=await api(path,{method:'POST'});if(out?.paymentUrl)window.open(out.paymentUrl,'_blank','noopener');onDone()}catch(e){setError((e as Error).message)}finally{setBusy('')}};
 const line=(rows:any[])=>rows.length?rows.map((r:any)=>money(r.amountMinor,r.currency)).join(' · '):money(0);
 return <div className="space-y-4">
  <ErrorNote code={error}/>
  <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
   <Metric icon={WalletCards} value={summary.activeSubscriptions||0} label="اشتراك نشط"/>
   <Metric icon={BadgeCheck} value={line(summary.collected||[])} label="محصّل"/>
   <Metric icon={AlertTriangle} value={line(summary.outstanding||[])} label="غير محصّل" tone="amber"/>
   <Metric icon={AlertTriangle} value={line(summary.overdue||[])} label={`متأخر · ${summary.overdueInvoices||0} فاتورة`} tone="amber"/>
  </div>

  {mine&&<div className="mizan-surface p-5">
   <div className="mizan-kicker">اشتراكي مع ميزان</div>
   <p className="mt-1 text-xs text-[#666c68]">هذا ما عليك أنت لمالك المنصة. فواتير جهاتك في الأسفل.</p>
   {(billing?.mySubscription||[]).length||(billing?.myInvoices||[]).length?<div className="mt-4 space-y-2">
    {(billing?.mySubscription||[]).map((x:any)=><div key={x.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-[#f3f1eb] p-3 text-xs"><span className="font-black">{x.planName||x.planId}</span><span dir="ltr">{money(x.amountMinor,x.currency)}</span><Badge variant={subTone(x.status)}>{SUB_AR[x.status]||x.status}</Badge></div>)}
    {(billing?.myInvoices||[]).slice(0,5).map((x:any)=><div key={x.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-[#e5e3dc] p-3 text-xs"><span dir="ltr" className="font-bold">{x.number}</span><span dir="ltr">{money(x.amountMinor,x.currency)}</span><span className="text-[10px] text-[#6c726e]">{date(x.issuedAt)}</span><Badge variant={invTone(x.status)}>{INV_AR[x.status]||x.status}</Badge></div>)}
   </div>:<div className="mt-4 rounded-xl bg-[#f3f1eb] p-4 text-xs text-[#666c68]">لا يوجد اشتراك أو فاتورة عليك حتى الآن.</div>}
  </div>}

  {(summary.revenueByMonth||[]).some((m:any)=>m.count>0)&&<div className="mizan-surface p-5">
   <div className="mizan-kicker">الإيرادات المحصّلة — آخر ١٢ شهرًا</div>
   <p className="mt-1 text-xs text-[#666c68]">من الفواتير المدفوعة فعلًا، لا من الفواتير المُصدَرة.</p>
   {(()=>{const rows=summary.revenueByMonth||[];const peak=Math.max(1,...rows.map((m:any)=>sumMinor(m.byCurrency||[])));return <div className="mt-5 flex items-end gap-1.5 overflow-x-auto pb-1">{rows.map((m:any)=>{const total=sumMinor(m.byCurrency||[]);const h=Math.round((total/peak)*100);return <div key={m.month} className="flex min-w-[42px] flex-1 flex-col items-center gap-1.5" title={`${m.month} · ${(m.byCurrency||[]).map((c:any)=>money(c.amountMinor,c.currency)).join(' · ')||money(0)}`}><div className="flex h-24 w-full items-end rounded-lg bg-[#f3f1eb]"><div className="w-full rounded-lg bg-[#214C40] transition-all" style={{height:`${total?Math.max(6,h):0}%`}}/></div><span className="text-[9px] text-[#6c726e]" dir="ltr">{m.month.slice(5)}</span></div>})}</div>})()}
   <div className="mt-4 flex flex-wrap gap-2 border-t border-[#e5e3dc] pt-4 text-[11px]">{(summary.collected||[]).length?(summary.collected||[]).map((c:any)=><span key={c.currency} className="rounded-full bg-[#e8f0eb] px-3 py-1 font-black text-[#214C40]" dir="ltr">{money(c.amountMinor,c.currency)}</span>):<span className="text-[#666c68]">لا تحصيل بعد.</span>}<span className="text-[#666c68]">إجمالي المحصّل منذ البداية</span></div>
  </div>}

  <div className="mizan-surface overflow-hidden">
   <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e3e1da] p-5">
    <div><h3 className="font-black">الاشتراكات</h3><p className="mt-1 text-xs text-[#666c68]">من يشترك، بأي باقة، وكم عليه الآن.</p></div>
    <Button size="sm" icon={<Plus className="h-4 w-4"/>} onClick={()=>setSubOpen(true)}>اشتراك جديد</Button>
   </div>
   <div className="divide-y divide-[#e5e3dc]">
    {subs.map((x:any)=><div key={x.id} className="grid gap-3 p-4 sm:grid-cols-[1fr_auto_auto_auto_auto] sm:items-center">
     <div className="min-w-0"><div className="font-black truncate">{x.subjectName}</div><div className="mt-1 text-[10px] text-[#6c726e]">{x.subjectType==='operator'?'مشغّل':'جهة'}{x.operatorName?` · ${x.operatorName}`:''} · {x.planName||x.planId}</div></div>
     <span className="text-xs" dir="ltr">{money(x.amountMinor,x.currency)}</span>
     <span className="text-[10px] text-[#6c726e]">حتى {date(x.currentPeriodEnd)}</span>
     {x.openAmountMinor>0?<Badge variant="amber">عليه {money(x.openAmountMinor,x.currency)}</Badge>:<Badge variant="emerald">لا مستحقات</Badge>}
     <div className="flex gap-2"><Badge variant={subTone(x.status)}>{SUB_AR[x.status]||x.status}</Badge>{x.status!=='canceled'&&<Button size="sm" variant="ghost" disabled={!!busy} onClick={()=>void act(`${base}/subscriptions/${encodeURIComponent(x.id)}/cancel`)}>إلغاء</Button>}</div>
    </div>)}
    {!subs.length&&<EmptyState icon={WalletCards} title="لا توجد اشتراكات" hint="أنشئ اشتراكًا لتبدأ الفوترة الدورية."/>}
   </div>
  </div>

  <div className="mizan-surface overflow-hidden">
   <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e3e1da] p-5">
    <div><h3 className="font-black">الفواتير</h3><p className="mt-1 text-xs text-[#666c68]">من دفع ومن لم يدفع، بوضوح.</p></div>
    <div className="flex flex-wrap gap-2">
     <Tabs value={filter} onChange={setFilter} items={[{id:'all',label:'الكل',count:invoices.length},{id:'open',label:'لم تُدفع',count:invoices.filter((i:any)=>i.status==='open').length},{id:'overdue',label:'متأخرة',count:invoices.filter((i:any)=>i.overdue).length},{id:'paid',label:'مدفوعة',count:invoices.filter((i:any)=>i.status==='paid').length}]}/>
     <Button size="sm" icon={<Plus className="h-4 w-4"/>} onClick={()=>setInvOpen(true)}>فاتورة جديدة</Button>
    </div>
   </div>
   <div className="divide-y divide-[#e5e3dc]">
    {shown.map((x:any)=><div key={x.id} className="grid gap-3 p-4 sm:grid-cols-[auto_1fr_auto_auto_auto] sm:items-center">
     <span dir="ltr" className="text-[11px] font-black text-[#214C40]">{x.number}</span>
     <div className="min-w-0"><div className="font-bold truncate text-sm">{x.subjectName}</div><div className="mt-1 text-[10px] text-[#6c726e]">{x.subjectType==='operator'?'مشغّل':'جهة'} · صدرت {date(x.issuedAt)}{x.dueAt?` · تستحق ${date(x.dueAt)}`:''}{x.paidAt?` · دُفعت ${date(x.paidAt)}`:''}</div></div>
     <span className="font-black tabular-nums" dir="ltr">{money(x.amountMinor,x.currency)}</span>
     <Badge variant={x.overdue?'rose':invTone(x.status)}>{x.overdue?`متأخرة ${x.daysOverdue} يومًا`:(INV_AR[x.status]||x.status)}</Badge>
     <div className="flex flex-wrap gap-2">{x.status==='open'&&<>{gateway?.configured&&<Button size="sm" disabled={!!busy} icon={<WalletCards className="h-4 w-4"/>} onClick={()=>void payOnline(x.id)}>{busy.endsWith(`${x.id}/checkout`)?'جارٍ فتح الدفع…':'ادفع إلكترونيًا'}</Button>}<Button size="sm" variant={gateway?.configured?'outline':undefined} disabled={!!busy} onClick={()=>void act(`${base}/invoices/${encodeURIComponent(x.id)}/pay`,{method:'manual'})}>تسجيل السداد</Button><Button size="sm" variant="outline" disabled={!!busy} onClick={()=>void act(`${base}/invoices/${encodeURIComponent(x.id)}/remind`)}>تذكير</Button><Button size="sm" variant="ghost" disabled={!!busy} onClick={()=>void act(`${base}/invoices/${encodeURIComponent(x.id)}/void`)}>إلغاء</Button></>}</div>
    </div>)}
    {!shown.length&&<EmptyState icon={FileSearch} title="لا توجد فواتير" hint="أصدر فاتورة لاشتراك قائم أو مبلغ لمرة واحدة."/>}
   </div>
  </div>

  <SubscriptionDialog open={subOpen} subjects={subjects} plans={plans} base={base} onClose={()=>setSubOpen(false)} onDone={()=>{setSubOpen(false);onDone()}}/>
  <InvoiceDialog open={invOpen} subjects={subjects} subs={subs} base={base} onClose={()=>setInvOpen(false)} onDone={()=>{setInvOpen(false);onDone()}}/>
 </div>;
};

const SubscriptionDialog=({open,subjects,plans,base,onClose,onDone}:{open:boolean;subjects:any[];plans:any[];base:string;onClose:()=>void;onDone:()=>void})=>{
 const [subject,setSubject]=useState(''),[planId,setPlanId]=useState(''),[startsAt,setStartsAt]=useState(new Date().toISOString().slice(0,10)),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 useEffect(()=>{if(open){setError('');setSubject(subjects[0]?`${subjects[0].type}:${subjects[0].id}`:'');setPlanId(plans[0]?.id||'')}},[open]);
 if(!open)return null;
 const save=async()=>{setBusy(true);setError('');try{const [subjectType,subjectId]=subject.split(':');await api(`${base}/subscriptions`,{method:'POST',body:JSON.stringify({subjectType,subjectId,planId,startsAt})});onDone()}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 return <Overlay onClose={onClose} title="اشتراك جديد"><form className="space-y-4 p-6" onSubmit={e=>{e.preventDefault();void save()}}><ErrorNote code={error}/>
  <label className="block"><span className="mizan-field-label">المشترك</span><select className="mizan-input" value={subject} onChange={e=>setSubject(e.target.value)}>{subjects.map(s=><option key={`${s.type}:${s.id}`} value={`${s.type}:${s.id}`}>{s.type==='operator'?'مشغّل':'جهة'} — {s.name}</option>)}</select></label>
  <label className="block"><span className="mizan-field-label">الباقة</span><select className="mizan-input" value={planId} onChange={e=>setPlanId(e.target.value)}><option value="">اختر باقة</option>{plans.map((p:any)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
  <Field type="date" label="بداية الاشتراك" value={startsAt} onChange={(e:any)=>setStartsAt(e.target.value)}/>
  <p className="text-xs leading-6 text-[#666c68]">يُحسب تاريخ التجديد تلقائيًا من دورة الباقة. السداد يُسجَّل يدويًا الآن، والبنية جاهزة لربط أي بوابة دفع لاحقًا دون تغيير البيانات.</p>
  <div className="flex justify-end"><Button disabled={busy||!subject||!planId}>{busy?'جارٍ الإنشاء…':'إنشاء الاشتراك'}</Button></div></form></Overlay>;
};

const InvoiceDialog=({open,subjects,subs,base,onClose,onDone}:{open:boolean;subjects:any[];subs:any[];base:string;onClose:()=>void;onDone:()=>void})=>{
 const [subject,setSubject]=useState(''),[subscriptionId,setSubscriptionId]=useState(''),[amount,setAmount]=useState(''),[currency,setCurrency]=useState('KWD'),[dueAt,setDueAt]=useState(''),[note,setNote]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 useEffect(()=>{if(open){setError('');setSubject(subjects[0]?`${subjects[0].type}:${subjects[0].id}`:'');setSubscriptionId('');setAmount('');setNote('')}},[open]);
 if(!open)return null;
 const matching=subs.filter((x:any)=>`${x.subjectType}:${x.subjectId}`===subject&&x.status!=='canceled');
 const save=async()=>{setBusy(true);setError('');try{const [subjectType,subjectId]=subject.split(':');await api(`${base}/invoices`,{method:'POST',body:JSON.stringify({subjectType,subjectId,subscriptionId:subscriptionId||undefined,amountMinor:Math.round(Number(amount)*100),currency,dueAt:dueAt||undefined,note:note||undefined})});onDone()}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 return <Overlay onClose={onClose} title="فاتورة جديدة"><form className="grid gap-4 p-6 sm:grid-cols-2" onSubmit={e=>{e.preventDefault();void save()}}><div className="sm:col-span-2"><ErrorNote code={error}/></div>
  <label className="block sm:col-span-2"><span className="mizan-field-label">على من</span><select className="mizan-input" value={subject} onChange={e=>{setSubject(e.target.value);setSubscriptionId('')}}>{subjects.map(s=><option key={`${s.type}:${s.id}`} value={`${s.type}:${s.id}`}>{s.type==='operator'?'مشغّل':'جهة'} — {s.name}</option>)}</select></label>
  <label className="block sm:col-span-2"><span className="mizan-field-label">مرتبطة باشتراك (اختياري)</span><select className="mizan-input" value={subscriptionId} onChange={e=>setSubscriptionId(e.target.value)}><option value="">بدون — مبلغ لمرة واحدة</option>{matching.map((x:any)=><option key={x.id} value={x.id}>{x.planName||x.planId} · {money(x.amountMinor,x.currency)}</option>)}</select></label>
  <Field label="المبلغ" type="number" min={0} step="0.01" value={amount} onChange={(e:any)=>setAmount(e.target.value)}/>
  <Field lang="en" data-mizan-kind="latin" dir="ltr" label="العملة" value={currency} maxLength={3} onChange={(e:any)=>setCurrency(e.target.value.toUpperCase())}/>
  <Field type="date" label="تاريخ الاستحقاق (اختياري)" value={dueAt} onChange={(e:any)=>setDueAt(e.target.value)}/>
  <Field label="ملاحظة (اختياري)" value={note} onChange={(e:any)=>setNote(e.target.value)}/>
  <div className="sm:col-span-2 flex justify-end"><Button disabled={busy||!subject||!(Number(amount)>0)}>{busy?'جارٍ الإصدار…':'إصدار الفاتورة'}</Button></div></form></Overlay>;
};

/* باقات المشغّل: نفس بنية خطط المنصة، لكن يملكها المشغّل ويبيعها لجهاته. */
const OperatorPlansPanel=({plans,onDone}:{plans:any[];onDone:()=>void})=>{
 const [open,setOpen]=useState(false),[editing,setEditing]=useState<any>(null),[error,setError]=useState('');
 return <div className="space-y-4">
  <ErrorNote code={error}/>
  <div className="flex justify-end"><Button size="sm" icon={<Plus className="h-4 w-4"/>} onClick={()=>{setEditing(null);setOpen(true)}}>باقة جديدة</Button></div>
  <div className="grid gap-3 lg:grid-cols-3">
   {plans.map((p:any)=><div key={p.id} className="mizan-panel p-5">
    <div className="flex items-center justify-between"><h3 className="text-lg font-black">{p.name}</h3><Badge variant={p.active?'emerald':'neutral'}>{p.active?'نشطة':'متوقفة'}</Badge></div>
    <div className="mt-2 text-sm font-bold" dir="ltr">{money(p.priceMinor,p.currency)} / {p.billingPeriod==='annual'?'سنة':'شهر'}</div>
    <div className="mt-5 space-y-3"><QuietRow label="مسابقات نشطة" value={p.limits.activeCompetitions}/><QuietRow label="متسابق سنويًا" value={p.limits.annualParticipants}/><QuietRow label="تخزين" value={gb(p.limits.storageBytes)}/><QuietRow label="فروع" value={p.limits.branches}/></div>
    <div className="mt-5 grid grid-cols-2 gap-2 border-t border-[#e5e3dc] pt-4">
     <Button size="sm" variant="outline" icon={<Pencil className="h-4 w-4"/>} onClick={()=>{setEditing(p);setOpen(true)}}>تعديل</Button>
     <Button size="sm" variant="ghost" icon={<Trash2 className="h-4 w-4"/>} onClick={async()=>{if(!window.confirm(`حذف باقة ${p.name}؟`))return;try{await api(`/api/saas/operator/plans/${encodeURIComponent(p.id)}`,{method:'DELETE'});onDone()}catch(e){setError((e as Error).message)}}}>حذف</Button>
    </div>
   </div>)}
   {!plans.length&&<div className="lg:col-span-3"><EmptyState icon={WalletCards} title="لا توجد باقات بعد" hint="أنشئ باقتك الأولى لتبيعها لجهاتك بأسعارك وحدودك أنت."/></div>}
  </div>
  <OperatorPlanDialog open={open} plan={editing} onClose={()=>{setOpen(false);setEditing(null)}} onDone={()=>{setOpen(false);setEditing(null);onDone()}}/>
 </div>;
};

const OperatorPlanDialog=({open,plan,onClose,onDone}:{open:boolean;plan:any;onClose:()=>void;onDone:()=>void})=>{
 const [f,setF]=useState(emptyPlanForm),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 useEffect(()=>{if(!open)return;setError('');setF(plan?{name:plan.name,currency:plan.currency,priceMinor:plan.priceMinor,active:plan.active,activeCompetitions:plan.limits.activeCompetitions,annualParticipants:plan.limits.annualParticipants,storageGb:plan.limits.storageBytes/1024**3,branches:plan.limits.branches,externalStorage:!!plan.features?.external_storage,whiteLabel:!!plan.features?.white_label,video:!!plan.features?.video}:emptyPlanForm)},[open,plan]);
 if(!open)return null;
 return <Overlay onClose={onClose} title={plan?'تعديل الباقة':'باقة جديدة'}><form className="grid gap-4 p-6 sm:grid-cols-2" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await api('/api/saas/operator/plans',{method:'PUT',body:JSON.stringify({id:plan?.id,name:f.name,currency:f.currency,priceMinor:f.priceMinor,billingPeriod:'annual',active:f.active,limits:{licensedOrganizations:1,activeCompetitions:f.activeCompetitions,annualParticipants:f.annualParticipants,storageBytes:f.storageGb*1024**3,branches:f.branches},features:{external_storage:f.externalStorage,white_label:f.whiteLabel,video:f.video}})});onDone()}catch(x){setError((x as Error).message)}finally{setBusy(false)}}}>
  <div className="sm:col-span-2"><ErrorNote code={error}/></div>
  <Field lang="ar" data-mizan-kind="arabic" label="اسم الباقة" value={f.name} onChange={(e:any)=>setF({...f,name:e.target.value})}/>
  <Field lang="en" data-mizan-kind="latin" dir="ltr" label="العملة" value={f.currency} maxLength={3} onChange={(e:any)=>setF({...f,currency:e.target.value.toUpperCase()})}/>
  <Field label="السعر بأصغر وحدة (فلس/سنت)" type="number" value={f.priceMinor} onChange={(e:any)=>setF({...f,priceMinor:Number(e.target.value)})}/>
  <Field label="المسابقات النشطة" type="number" value={f.activeCompetitions} onChange={(e:any)=>setF({...f,activeCompetitions:Number(e.target.value)})}/>
  <Field label="المتسابقون سنويًا" type="number" value={f.annualParticipants} onChange={(e:any)=>setF({...f,annualParticipants:Number(e.target.value)})}/>
  <Field label="التخزين GB" type="number" value={f.storageGb} onChange={(e:any)=>setF({...f,storageGb:Number(e.target.value)})}/>
  <Field label="الفروع" type="number" value={f.branches} onChange={(e:any)=>setF({...f,branches:Number(e.target.value)})}/>
  <div className="sm:col-span-2 flex flex-wrap gap-4 text-xs font-bold"><label className="mizan-consent"><input type="checkbox" checked={f.active} onChange={e=>setF({...f,active:e.target.checked})}/><span>الباقة نشطة</span></label>{[['التخزين الخاص','externalStorage'],['العلامة البيضاء','whiteLabel'],['الفيديو','video']].map(([label,key])=><label key={key} className="mizan-consent"><input type="checkbox" checked={(f as any)[key]} onChange={e=>setF({...f,[key]:e.target.checked})}/><span>{label}</span></label>)}</div>
  <div className="sm:col-span-2 flex justify-end"><Button disabled={!f.name||busy}>{busy?'جارٍ الحفظ…':'حفظ الباقة'}</Button></div></form></Overlay>;
};
